/* @lc app=leetcode id=3376 lang=kotlin */ class Solution { fun findMinimumTime(strength: List<Int>, k: Int): Int = IntArray(1 shl strength.size) { if (it == 0) 0 else 1_000_000_000 }.also { dp -> dp.indices.forEach { m -> strength.indices.filter { m shr it and 1 == 0 }.forEach { i -> dp[m or (1 shl i)] = minOf(dp[m or (1 shl i)], dp[m] + (strength[i] + k * Integer.bitCount(m)) / (1 + k * Integer.bitCount(m))) } } }.last() }